style.css:
@-moz-document domain("roblox.com") {
/* Arrière-plan avec l'image de lys */
    html {
        background: url("https://i.imgur.com/sL5uTQp.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Couleurs globales */
    body {
        background-color: rgba(10, 10, 10, 0.85) !important; /* noir semi-transparent */
        color: #f5e8e8 !important; /* crème clair */
        font-family: "Segoe UI", sans-serif !important;
    }

    /* Barre de navigation */
    .navbar, .nav-container {
        background-color: rgba(40, 10, 20, 0.85) !important; /* bordeaux foncé */
        border-bottom: 2px solid #a65c6a !important; /* rose foncé */
    }

    /* Liens */
    a {
        color: #c78292 !important; /* rose moyen */
        text-decoration: none !important;
    }
    a:hover {
        color: #f5b6c1 !important; /* rose clair */
    }

    /* Boutons */
    button, .btn-primary {
        background-color: #8a3f4c !important; /* bordeaux */
        color: #f5e8e8 !important; /* crème */
        border-radius: 8px !important;
        border: none !important;
        transition: all 0.2s ease-in-out;
    }
    button:hover, .btn-primary:hover {
        background-color: #b45564 !important; /* rose foncé */
        transform: scale(1.05);
    }

    /* Profils et cartes */
    .profile-header, .card-item {
        background-color: rgba(30, 10, 20, 0.8) !important; /* bordeaux noirci */
        border-radius: 10px !important;
        padding: 10px !important;
        border: 1px solid rgba(245, 184, 193, 0.4) !important; /* contour rose clair */
    }

    /* Titres */
    h1, h2, h3 {
        color: #eab0b7 !important; /* rose pastel */
    }
}
